// Platform-specific definitions of a numeric thread ID type and an invalid value
namespace moodycamel {
namespace details {
template <typename thread_id_t> struct thread_id_converter {
  typedef thread_id_t thread_id_numeric_size_t;
  typedef thread_id_t thread_id_hash_t;
  static thread_id_hash_t prehash(thread_id_t const &id) { return id; }
};
} // namespace details
} // namespace moodycamel
#if defined(_WIN32)
#include <windows.h> // GetCurrentThreadId()
namespace moodycamel {
namespace details {
typedef DWORD thread_id_t;
static const thread_id_t invalid_thread_id = 0;
#if defined(MCDBGQ_WIN32_X86)
const int ThreadIdTidOffset = 0; // GetCurrentThreadId() is from FS segment register on 32-bit x86
#else
const int ThreadIdTidOffset = -1; // Not applicable
#endif
} // namespace details
} // namespace moodycamel
#elif defined(__GNUC__) || defined(__clang__)
#include <pthread.h> // pthread_self()
namespace moodycamel {
namespace details {
typedef pthread_t thread_id_t;
static const thread_id_t invalid_thread_id = 0;
const int ThreadIdTidOffset = -1; // Not applicable
template <> struct thread_id_converter<thread_id_t> {
  typedef unsigned long long thread_id_numeric_size_t;
#if defined(__APPLE__) && TARGET_OS_MAC && !TARGET_OS_IPHONE && !TARGET_OS_SIMULATOR
  // macOS uses a 64-bit thread ID, meaning it needs to be hashed in order to fit in a 32-bit slot
  // (when used for explicit producers)
  typedef uint32_t thread_id_hash_t;
#else
  // Using the thread ID directly is safe on other platforms
  typedef thread_id_numeric_size_t thread_id_hash_t;
#endif
  static thread_id_hash_t prehash(thread_id_t const &id) {
#if defined(__APPLE__) && TARGET_OS_MAC && !TARGET_OS_IPHONE && !TARGET_OS_SIMULATOR
    // While pthread_self() returns a 64-bit value on macOS, the part that changes is only the lower ~32
    // bits (verified empirically). Plus, it appears to be fairly linearly assigned. So we just mask
    // an an offset.
    return static_cast<thread_id_hash_t>(reinterpret_cast<uint64_t>(id) >> 8);
#else
    return static_cast<thread_id_hash_t>(id);
#endif
  }
};
} // namespace details
} // namespace moodycamel
#else
// Fallback if no specific platform was identified
#include <thread> // std::this_thread::get_id()
#include <functional> // std::hash
namespace moodycamel {
namespace details {
typedef std::thread::id thread_id_t;
static const thread_id_t invalid_thread_id = std::thread::id(); // Default ctor creates invalid ID

const int ThreadIdTidOffset = -1; // Not applicable
template <> struct thread_id_converter<thread_id_t> {
  typedef std::size_t thread_id_numeric_size_t;
  typedef std::size_t thread_id_hash_t;
  static thread_id_hash_t prehash(thread_id_t const &id) { return std::hash<std::thread::id>()(id); }
};
} // namespace details
} // namespace moodycamel
#endif

